gzK(){return"Nexus \u043f\u043e\u043b\u0443\u0447\u0435\u043d"},
gzq(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0441\u0432\u044f\u0437\u0430\u0442\u044c\u0441\u044f \u0441\u043e \u0441\u043b\u0443\u0436\u0431\u043e\u0439 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438."},
gzi(){return"\u042d\u0442\u043e\u0442 \u043a\u043e\u0434 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u0438\u043b\u0438 PIN \u043d\u0435\u0432\u0435\u0440\u0435\u043d."},
gzp(){return"\u0421\u043b\u0438\u0448\u043a\u043e\u043c \u043c\u043d\u043e\u0433\u043e \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0445 PIN. \u042d\u0442\u0430 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u043d\u0430 \u0432\u0440\u0435\u043c\u044f."},
gzn(){return"\u042d\u0442\u0430 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u0438\u0441\u0442\u0435\u043a\u043b\u0430. \u041f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u043d\u043e\u0432\u044b\u0439 \u043a\u043e\u0434."},
gzo(){return"\u042d\u0442\u043e\u0439 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435\u0442 \u2014 \u0435\u0451 \u043f\u0440\u0438\u043d\u044f\u043b\u0438 \u0438\u043b\u0438 \u043e\u0442\u043c\u0435\u043d\u0438\u043b\u0438."},
gzr(){return"\u0414\u0440\u0443\u0433\u043e\u0435 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u0435\u0449\u0451 \u043d\u0435 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u043e \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0443."},
gzx(){return"\u042d\u0442\u043e\u0442 Nexus \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u043e\u0434\u043d\u0430 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0430."},
gzm(){return"\u042d\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044f \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u0430. \u041d\u0430\u0447\u043d\u0438\u0442\u0435 \u0437\u0430\u043d\u043e\u0432\u043e."},
gzj(){return"\u0421\u0441\u044b\u043b\u043a\u0430 \u043d\u0435\u043f\u043e\u043b\u043d\u0430\u044f \u2014 \u0447\u0430\u0441\u0442\u044c \u0441 \u043a\u043b\u044e\u0447\u043e\u043c \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0438\u043b\u0438 \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u0430."},
gzs(){return"\u041e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043b \u0442\u043e\u043b\u044c\u043a\u043e QR-\u043a\u043e\u0434. \u041e\u0442\u0441\u043a\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u0435\u0433\u043e \u0432\u043c\u0435\u0441\u0442\u043e \u0432\u0432\u043e\u0434\u0430."},
gzk(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b."},
