gzN(){return"\u041e\u0442\u043f\u0440\u0430\u0432\u043a\u0430\u2026"},
gzd(){return"\u0421\u0441\u044b\u043b\u043a\u0430 \u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0430"},
gnV(){return"\u041e\u0442\u043c\u0435\u043d\u0430"},
gzE(){return"\u0418\u043b\u0438 \u0432\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0441\u0441\u044b\u043b\u043a\u0443 \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438"},
gzF(){return"\u0421\u0441\u044b\u043b\u043a\u0430 \u043d\u0435\u0441\u0451\u0442 \u043a\u043b\u044e\u0447 \u0432 \u0441\u0435\u0431\u0435, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0434\u0430\u0436\u0435 \u0435\u0441\u043b\u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043b \u0442\u043e\u043b\u044c\u043a\u043e QR-\u043a\u043e\u0434."},
