gnY(){return"\u041f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0446\u0456\u043b\u0438\u0439 Nexus \u043d\u0430 \u0456\u043d\u0448\u0438\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439. \u0411\u0435\u0437 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043f\u0438\u0441\u0443 \u0439 \u0431\u0435\u0437 \u043d\u0430\u043b\u0430\u0448\u0442\u0443\u0432\u0430\u043d\u043d\u044f: \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439-\u0432\u0456\u0434\u043f\u0440\u0430\u0432\u043d\u0438\u043a \u043f\u043e\u043a\u0430\u0437\u0443\u0454 \u043a\u043e\u0434, \u043e\u0442\u0440\u0438\u043c\u0443\u0432\u0430\u0447 \u0439\u043e\u0433\u043e \u0432\u0432\u043e\u0434\u0438\u0442\u044c, \u0430 \u043f\u0440\u043e\u043c\u0456\u0436\u043d\u0430 \u043a\u043e\u043f\u0456\u044f \u0437\u043d\u0438\u043a\u0430\u0454 \u0449\u043e\u0439\u043d\u043e \u0434\u0456\u0439\u0434\u0435."},
gzR(){return"\u041d\u0430\u0434\u0456\u0441\u043b\u0430\u0442\u0438"},
gzQ(){return"\u041e\u0442\u0440\u0438\u043c\u0430\u0442\u0438"},
gzD(){return"Nexus"},
gzG(){return"\u0421\u043f\u0435\u0440\u0448\u0443 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 Nexus, \u044f\u043a\u0438\u0439 \u0445\u043e\u0447\u0435\u0442\u0435 \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u0442\u0438."},
gza(){return"\u0414\u043e\u0437\u0432\u043e\u043b\u0438\u0442\u0438 \u043e\u0442\u0440\u0438\u043c\u0430\u043d\u043d\u044f \u0432\u0432\u0435\u0434\u0435\u043d\u043d\u044f\u043c \u043a\u043e\u0434\u0443"},
gzb(){return"\u0423\u0432\u0456\u043c\u043a\u043d\u0435\u043d\u043e \u2014 \u0456\u043d\u0448\u0438\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043c\u043e\u0436\u0435 \u0432\u0432\u0435\u0441\u0442\u0438 \u043a\u043e\u0434 \u0456 PIN, \u043d\u0430\u0442\u043e\u043c\u0456\u0441\u0442\u044c \u0441\u043b\u0443\u0436\u0431\u0430 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u0454 \u043a\u043b\u044e\u0447, \u0437\u0430\u043f\u0435\u0447\u0430\u0442\u0430\u043d\u0438\u0439 \u0446\u0438\u043c PIN, \u0434\u043e\u043a\u0438 \u0442\u0440\u0438\u0432\u0430\u0454 \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f. \u0412\u0438\u043c\u043a\u043d\u0435\u043d\u043e \u2014 \u0454\u0434\u0438\u043d\u0438\u0439 \u0432\u0445\u0456\u0434 \u0447\u0435\u0440\u0435\u0437 QR-\u043a\u043e\u0434, \u0456 \u0441\u043b\u0443\u0436\u0431\u0430 \u0432\u0437\u0430\u0433\u0430\u043b\u0456 \u043d\u0435 \u043c\u043e\u0436\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u0438 \u0444\u0430\u0439\u043b."},
